def solve():
    def find_expressions(index, current_expression, current_value, previous_operand, num, target, result):
        if index == len(num):
            if current_value == target:
                result.append(current_expression)
            return

        for i in range(index, len(num)):
            current_num_str = num[index:i+1]
            if len(current_num_str) > 1 and current_num_str[0] == '0':
                break
            current_num = int(current_num_str)

            if index == 0:
                find_expressions(i + 1, current_num_str, current_num, current_num, num, target, result)
            else:
                find_expressions(i + 1, current_expression + '+' + current_num_str, current_value + current_num, current_num, num, target, result)
                find_expressions(i + 1, current_expression + '-' + current_num_str, current_value - current_num, -current_num, num, target, result)
                find_expressions(i + 1, current_expression + '*' + current_num_str, current_value - previous_operand + previous_operand * current_num, previous_operand * current_num, num, target, result)

    def get_expressions(num, target):
        result = []
        find_expressions(0, "", 0, 0, num, target, result)
        return result

